export const abrahamB2FinalChallengeExercises: Exercise[] = [
{ id: 'ab-b2-f1', type: 'multiple-choice', title: 'A Unique Name', instructions: 'Choose the answer the story states.', question: 'Chapter 1 calls “Allah’s friend” a unique name. What makes this title unique, according to the story?', options: ['It was not given to any other prophet before Abraham.', 'It was the name his father Azer gave him as a child.', 'It is the name of the fourteenth surah of the Qur’an.', 'The people of Babylon used it for their own king.'], correctAnswer: 0, explanation: 'Chapter 1 gives Abraham the name “Allah’s friend” and adds: “This title was not given to any other prophet before.” The last chapter returns to the title: “During Hajj Muslims are reminded of many events of Allah’s beloved “friend” Abraham (pbuh) and his family.” (Chapter 35)', feedback: { correct: 'Yes. The word “unique” is explained in the next sentence: no prophet before him had this title.', incorrect: 'Read the sentence that follows the title in Chapter 1. What does it say about other prophets?' } },
{ id: 'ab-b2-f2', type: 'multiple-choice', title: 'A Question to the Statues', instructions: 'Choose the purpose the story gives.', question: 'In the temple Abraham asks the statues: “Will you not eat of the offering before you?” What was his real purpose?', options: ['He hoped that the statues would finally move.', 'He was mocking them, since he knew they could not eat.', 'He wanted the priests to hear him and come back.', 'He was checking whether the food was still warm.'], correctAnswer: 1, explanation: 'Chapter 18 explains: “He was mocking them, for he knew they would not eat.” His question showed that the statues were “lifeless, silent, and entirely helpless” (Chapter 7).', feedback: { correct: 'Yes. The question was ironic: Abraham asked something he knew the statues could never do.', incorrect: 'Read the sentence right after the question in Chapter 18. What was Abraham doing?' } },
{ id: 'ab-b2-f3', type: 'multiple-choice', title: 'Fame Without Followers', instructions: 'Choose the answer the story supports.', question: 'After the fire and the debate with Nimrod, Abraham’s fame spread throughout Babylonia. What was the result of his call among his own people?', options: ['Most of the people followed him to Egypt.', 'The king’s priests finally accepted his message.', 'Only one woman and one man shared his belief.', 'His father Azer left the idols and joined him.'], correctAnswer: 2, explanation: 'Chapter 24 says: “However, in spite of his love and care for his people, they left him alone. Only one woman and one man of his people shared his belief in Allah.” Chapter 22 gives one reason: “people did not dare to follow Abraham (pbuh) out of fear of rulers.”', feedback: { correct: 'Yes. Everyone talked about Abraham, but fear of the rulers kept almost everyone away from his faith.', incorrect: 'Read the end of Chapter 24. How many of his people believed, and who were they?' } },
{ id: 'ab-b2-f4', type: 'true-false', title: 'A Father’s Plan', instructions: 'Decide whether the statement is true or false.', question: 'Abraham’s father wanted his son to become a priest one day.', correctAnswer: true, explanation: 'Chapter 8 says: “His father wanted him to become a priest when he grew up, which made things even worse.” Azer “only wanted his son to show respect to those statues”.', feedback: { correct: 'True. Azer planned a life in the temple for his son, the very place Abraham disliked most.', incorrect: 'Read the first paragraph of Chapter 8. What did Azer want Abraham to become?' } },
{ id: 'ab-b2-f5', type: 'true-false', title: 'Father and Son Again', instructions: 'Decide whether the statement is true or false.', question: 'When Abraham and Ishmael met again to build the Ka’ba, Ishmael was still a little child.', correctAnswer: false, explanation: 'Ishmael was “still a little child” when he was taken to Mecca (Chapter 26), but Chapter 33 says: “After a separation of several years, the father and son came together again. At that time, Ishmael was about thirty years old.”', feedback: { correct: 'Right. Many years had passed, and Ishmael was a grown man who could help his father build.', incorrect: 'Compare Chapter 26 with Chapter 33. How old was Ishmael when the building began?' } },
{ id: 'ab-b2-f6', type: 'matching', title: 'People Around Abraham', instructions: 'Match each person or group with what the story tells about them.', question: 'Who are these people in Abraham’s story?', matchingPairs: [{ left: 'Azer', right: 'presented as Nimrod’s idol maker' }, { left: 'Sarah', right: 'suggested that Abraham marry Hagar' }, { left: 'Lot', right: 'believed in Abraham and later became a prophet' }, { left: 'the Jurham tribe', right: 'the people Ishmael learned Arabic from' }], correctAnswer: { Azer: 'presented as Nimrod’s idol maker', Sarah: 'suggested that Abraham marry Hagar', Lot: 'believed in Abraham and later became a prophet', 'the Jurham tribe': 'the people Ishmael learned Arabic from' }, explanation: 'Chapter 4: “Azer is presented in Islamic sources as Nimrod’s idol maker.” Chapter 25: “Therefore, she suggested Abraham (pbuh) get married to Hagar.” Chapter 24: “The man’s name was Lot and he later became a prophet.” Chapter 31: “Ishmael learned Arabic from them and they all loved and admired Ishmael because of his gentle character.”', feedback: { correct: 'Yes. Each of these people plays a part in Abraham’s life, from his father’s house to Mecca.', incorrect: 'Look again at Chapters 4, 24, 25 and 31. What does each chapter say about these people?' } },
{ id: 'ab-b2-f7', type: 'matching', title: 'Words and Attitudes', instructions: 'Match each of Abraham’s sayings with the attitude it shows.', question: 'What does each saying show about Abraham?', matchingPairs: [{ left: '“Allah is sufficient for me.”', right: 'complete trust just before the fire' }, { left: '“I will ask my Lord to forgive you”', right: 'kindness towards a father who threatened him' }, { left: '“I will emigrate for the sake of my Lord.”', right: 'leaving his homeland for Allah' }, { left: '“Accept this service from us”', right: 'humility while doing a great task' }], correctAnswer: { '“Allah is sufficient for me.”': 'complete trust just before the fire', '“I will ask my Lord to forgive you”': 'kindness towards a father who threatened him', '“I will emigrate for the sake of my Lord.”': 'leaving his homeland for Allah', '“Accept this service from us”': 'humility while doing a great task' }, explanation: 'Chapter 22: these were “His last words before entering the flames”. Chapter 14: Abraham answers his father right after “If you do not stop this, I will stone you.” Chapter 25: he speaks when he “realized that no one else was going to believe in his call”. Chapter 34: Abraham and Ishmael pray while they build the Ka’ba.', feedback: { correct: 'Yes. In every scene, Abraham’s words show the same trust in Allah, in a different way.', incorrect: 'Think about where each saying comes: before the fire, after a threat, before a journey, or during the building.' } },
{ id: 'ab-b2-f8', type: 'fill-blanks', title: 'Wood for the Fire', instructions: 'Complete the sentence from Chapter 20 with one word: service, gift, warning or punishment.', question: 'How were the citizens told to see their work of gathering wood?', fillBlanksText: 'All the citizens were ordered to gather wood as a [blank] to their gods.', correctAnswer: ['service'], explanation: 'Chapter 20 says: “All the citizens were ordered to gather wood as a service to their gods.” The rulers presented their revenge as worship, although these gods could not even protect themselves from Abraham’s axe (Chapter 18).', feedback: { correct: 'Yes. The word “service” shows how the rulers turned their revenge into a religious duty.', incorrect: 'Read the end of Chapter 20. The people were told that gathering wood was something they did for their gods.' } },
{ id: 'ab-b2-f9', type: 'fill-blanks', title: 'A House for All People', instructions: 'Complete the sentence from Chapter 35 with one word: race, city, age or language.', question: 'Who was the Ka’ba built for?', fillBlanksText: 'He built a place of worship for all people, not just people of a chosen [blank] or color.', correctAnswer: ['race'], explanation: 'Chapter 35 says: “He built a place of worship for all people, not just people of a chosen race or color. This actually reminds us of the oneness of Allah.”', feedback: { correct: 'Yes. One house for all people reflects the belief in one Allah for all people.', incorrect: 'Read the middle of Chapter 35. Which word goes together with “color”?' } },
{ id: 'ab-b2-f10', type: 'sequencing', title: 'From Babylon to Mecca', instructions: 'Put these events in the order of the story.', question: 'How does Abraham’s life unfold from Babylon to Mecca?', sequencingItems: [{ id: '4', text: 'Nimrod frees one man sentenced to death and puts the other to death.' }, { id: '1', text: 'Abraham laughs when his father says Marduk’s big ears show deep knowledge.' }, { id: '6', text: 'Abraham stands on the stone of Al-Maqam while Ishmael hands him the stones.' }, { id: '3', text: 'Abraham hangs his axe on the neck of the one idol he did not break.' }, { id: '5', text: 'Abraham leaves Hagar and Ishmael with a skin of water and a bag of dates.' }, { id: '2', text: 'Abraham sits in a cave on a mountain and looks at the planets and stars.' }], correctAnswer: ['1', '2', '3', '4', '5', '6'], explanation: 'Marduk (Chapters 6–7), the night on the mountain (Chapter 8), the broken idols (Chapter 18), Nimrod (Chapter 23), the valley of Mecca (Chapter 27) and the building of the Ka’ba (Chapter 34).', feedback: { correct: 'Yes. The story follows Abraham from his father’s workshop to the House of Allah.', incorrect: 'Remember that Nimrod called Abraham only after he “had emerged from the fire unharmed”.' } },
];
